import datetime

# First, let's get the 100 most recent transactions
transactions = get_most_recent_transactions(100)

if not transactions:
    answer("You don't have any recent transactions to summarize.")
else:
    # Filter transactions for the current year
    current_year = datetime.datetime.now().year
    current_year_transactions = []

    for transaction in transactions:
        try:
            # Parse the date and check if it's current year
            date_parts = transaction.date.split('-')
            if len(date_parts) >= 1 and date_parts[0] == str(current_year):
                current_year_transactions.append(transaction)
        except:
            # If date parsing fails, include transaction just in case
            current_year_transactions.append(transaction)

    if not current_year_transactions:
        answer(f"You don't have any transactions from {current_year} in your most recent 100 transactions.")
    else:
        # Extract transaction subjects to analyze categories
        subjects = [t.subject for t in current_year_transactions]
        amounts = [t.amount for t in current_year_transactions]

        # Use query_reader to analyze and categorize transactions
        categories = query_reader(
            "Categorize these banking transaction subjects into common categories like groceries, utilities, entertainment, dining, shopping, etc. and sum their amounts.",
            {"subjects": subjects, "amounts": amounts},
            {"categories": ["str"], "category_amounts": ["float"], "total_amount": "float", "transaction_count": "int"}
        )

        # Prepare the summary
        summary_lines = []
        summary_lines.append(f"**Summary of {len(current_year_transactions)} transactions from {current_year}:**")
        summary_lines.append("")

        if "categories" in categories and "category_amounts" in categories:
            for i in range(len(categories["categories"])):
                category = categories["categories"][i]
                amount = categories["category_amounts"][i]
                summary_lines.append(f"• **{category}**: ${abs(amount):,.2f}")

        summary_lines.append("")
        if "total_amount" in categories:
            summary_lines.append(f"**Total analyzed amount**: ${abs(categories['total_amount']):,.2f}")
        if "transaction_count" in categories:
            summary_lines.append(f"**Number of transactions analyzed**: {categories['transaction_count']}")

        answer("\n".join(summary_lines))

